/* ===== გადაცემა თამაშში (CEF/launcher-ის ადაპტერი) ===== */
const $=s=>document.querySelector(s);
const emit=(e,d)=>{try{const j=JSON.stringify(d||{});if(window.cef&&cef.emit)cef.emit(e,j);else if(window.mp&&mp.trigger)mp.trigger(e,j)}catch(_){}};
const S={name:'Aurora',id:1323,online:930,wanted:0,cash:0,bank:0,hunger:100,thirst:100,greenzone:false,demorgan:false,x2:false,x4:false,
 weather:{t:15,txt:'სუფთა'},talking:false,radio:false,hud:true,userHide:false,srv:!(window.cef||window.mp),health:100,armor:0,weapon:0,ammo:0,
 veh:{in:false,speed:0,gear:'N',fuel:0,max:100,engine:false,locked:false,belt:false},quest:{left:CFG.questStart,done:false,floor:0,min:-1,ready:false,vis:true,sync:0}};
const DAYS=['კვირა','ორშაბათი','სამშაბათი','ოთხშაბათი','ხუთშაბათი','პარასკევი','შაბათი'];
const GUNS={1:'Brass Knuckles',2:'Golf Club',3:'Nightstick',4:'Knife',5:'Baseball Bat',6:'Shovel',7:'Pool Cue',8:'Katana',9:'Chainsaw',10:'Dildo',11:'Dildo',12:'Vibrator',13:'Vibrator',14:'Flowers',15:'Cane',16:'Grenade',17:'Tear Gas',18:'Molotov',22:'Pistol',23:'Silenced Pistol',24:'Desert Eagle',25:'Shotgun',26:'Sawn-off',27:'Combat Shotgun',28:'Micro SMG',29:'MP5',30:'AK-47',31:'M4',32:'Tec-9',33:'Rifle',34:'Sniper',35:'RPG',36:'HS Rocket',37:'Flamethrower',38:'Minigun',39:'Satchel',40:'Detonator',41:'Spray Can',42:'Extinguisher',43:'Camera',44:'Night Vision',45:'Thermal',46:'Parachute'};
const p2=n=>String(n).padStart(2,'0');
const shown={cash:0,bank:0};

function notify(type,text,ms){ms=ms||4000;
 const T={error:['warn','#e02424','Error'],warn:['warn','#ff9f1c','Warning'],info:['info','#3b9dff','Info'],success:['check','#2fbf3f','Success']},[ic,c,tt]=T[type]||T.info,box=$('#notes');
 while(box.children.length>=4)rm(box.firstChild);
 const n=document.createElement('div');n.className='nt';n.style.setProperty('--c',c);
 n.innerHTML='<i><svg class="i"><use href="#'+ic+'"/></svg></i><div class="tx"><em class="tt"></em><span></span></div><b style="animation-duration:'+ms+'ms"></b>';
 n.querySelector('.tt').textContent=tt;n.querySelector('span').textContent=text;box.appendChild(n);setTimeout(()=>rm(n),ms)}
function rm(n){if(!n||n._r)return;n._r=1;n.classList.add('out');setTimeout(()=>n.remove(),350)}

function tween(k,el){const from=shown[k],to=S[k],t0=performance.now();
 el.parentElement.classList.remove('up','dn');if(from!==to){el.parentElement.classList.add(to>from?'up':'dn');setTimeout(()=>el.parentElement.classList.remove('up','dn'),900)}
 (function f(t){const p=Math.min(1,(t-t0)/600);shown[k]=Math.round(from+(to-from)*p);el.textContent='$'+shown[k].toLocaleString('en-US');if(p<1)requestAnimationFrame(f)})(t0)}

const stars=$('#stars');for(let i=0;i<5;i++)stars.insertAdjacentHTML('beforeend','<svg viewBox="0 0 24 24"><use href="#star"/></svg>');
const prev={};
function gunImg(id){const b=$('#gb'),i=$('#gi'),src=GUN_IMG[id]||(CFG.gunImgBase?CFG.gunImgBase+id+'.png':'');
  if(prev.gimg===src)return;prev.gimg=src;if(!src){b.classList.add('no');return}
  i.onload=()=>b.classList.remove('no');i.onerror=()=>b.classList.add('no');i.src=src}
function render(){
 $('#online').textContent=S.online;$('#name').textContent=S.name;$('#pid').textContent='#'+String(S.id).padStart(5,'0');
 [...stars.children].forEach((s,i)=>s.classList.toggle('on',i<S.wanted));
 $('#x2').classList.toggle('hide',!S.x2);$('#x4').classList.toggle('hide',!S.x4);
 S.hud=S.srv&&!S.userHide;$('#hud').classList.toggle('off',!S.hud);
 const set=(el,v)=>{el.querySelector('.fl').style.height=v+'%';el.classList.toggle('low',v<20)};
 set($('#sT'),S.thirst);set($('#sH'),S.hunger);set($('#sHP'),S.health);set($('#sAR'),S.armor);
 $('#sAR').classList.remove('hide');
 $('#sT').classList.remove('hide');
 const wn=GUNS[S.weapon];$('#gun').classList.toggle('show',!!wn);if(wn){$('#gn').textContent=wn;$('#ga').textContent=S.ammo>0?S.ammo:'';gunImg(S.weapon)}
 $('#sG').classList.toggle('hide',!S.greenzone);$('#sD').classList.toggle('hide',!S.demorgan);
 $('#wt').textContent=(S.weather.t>=0?'+ ':'- ')+Math.abs(S.weather.t);$('#wd').textContent=S.weather.txt;
 if(prev.cash!==S.cash){tween('cash',$('#mc span'));prev.cash=S.cash}
 if(prev.bank!==S.bank){tween('bank',$('#mb span'));prev.bank=S.bank}
 const dV=$('#dV'),dR=$('#dR');if(dV)dV.classList.toggle('on',S.talking);if(dR)dR.classList.toggle('on',S.radio);
 const v=S.veh;$('#veh').classList.toggle('show',v.in);
 $('#spd').textContent=Math.round(v.speed);$('#gear').textContent=v.gear;
 $('#vE').setAttribute('class',v.engine?'ok':'');$('#vB').setAttribute('class',v.belt?'ok':'bad');$('#vL').setAttribute('class',v.locked?'pk':'');
 $('#fv').textContent=Math.round(v.fuel);$('#fm').textContent='/'+v.max+'L';$('#fuel').classList.toggle('low',v.fuel/v.max<.15);
 const q=S.quest,el=CFG.questStart-q.left,h=Math.min(CFG.questGoal,Math.floor(el/3600));
 $('#qh').textContent=h+'/';$('#qg').textContent=CFG.questGoal;
 const L=Math.max(0,q.left);$('#qt').textContent=q.ready?'მზადაა':(L?Math.floor(L/3600)+':'+p2(Math.floor(L%3600/60))+':'+p2(L%60):'0:00');
  $('#qsm').textContent=q.ready?'ინვენტარში':'დარჩენილია';$('#quest').style.display=q.vis?'':'none';
}
let tzFmt=null;try{tzFmt=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Tbilisi',hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',weekday:'short'})}catch(_){}
const WD={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
function clock(){let H,M,D,Mo,Y,W;
 if(tzFmt){const o={};tzFmt.formatToParts(new Date()).forEach(x=>o[x.type]=x.value);H=o.hour==='24'?'00':o.hour;M=o.minute;D=o.day;Mo=o.month;Y=o.year;W=WD[o.weekday]}
 else{const d=new Date();H=p2(d.getHours());M=p2(d.getMinutes());D=p2(d.getDate());Mo=p2(d.getMonth()+1);Y=d.getFullYear();W=d.getDay()}
 $('#clk').textContent=H+':'+M;$('#dt').textContent=D+'.'+Mo+'.'+Y;$('#dy').textContent=DAYS[W]}

/* ===== გარე API ===== */
const HUD=window.HUD={
 update(o){for(const k in o){const v=o[k];if(v&&typeof v==='object'&&S[k]&&typeof S[k]==='object')Object.assign(S[k],v);else S[k]=v}render()},
 notify, eat(v){S.hunger=v==null?100:v;render()}, drink(v){S.thirst=v==null?100:v;render()},
 setGreenZone(b){const was=S.greenzone;S.greenzone=!!b;if(was!==!!b)notify(b?'success':'warn',b?'თქვენ შეხვედით გრინ ზონაში':'თქვენ დატოვეთ გრინ ზონა');render()},
 setDemorgan(b){const was=S.demorgan;S.demorgan=!!b;if(was!==!!b&&b)notify('warn','თქვენ ხართ დემორგანში');render()},
 setEngine(b){S.veh.engine=!!b;notify(b?'success':'info',b?'ძრავი წარმატებით დაიქოქა':'ძრავი გამორთულია');render()},
 setLocked(b){S.veh.locked=!!b;notify(b?'info':'success',b?'ავტომობილი დაკეტილია':'ავტომობილი გახსნილია');render()},
 setBelt(b){S.veh.belt=!!b;notify('info',b?'ღვედი შეკრულია':'ღვედი გახსნილია');render()},
 setVehicle(b){S.veh.in=!!b;if(b&&!S.veh.engine)notify('error','ძრავის დასაქოქად გამოიყენეთ 2');if(!b)S.veh.speed=0;render()},
 setPaydayBoost(active){S.x2=!!Number(active);render()},
 unknownCommand(c){notify('error','უცნობი ბრძანება: '+(c||''))},
 setVisible(b){S.userHide=!b;render()}
};
window.addEventListener('message',e=>{let d=e.data;if(typeof d==='string'){try{d=JSON.parse(d)}catch(_){return}}
 if(d&&d.action&&typeof HUD[d.action]==='function')HUD[d.action](d.data)});
if(window.cef&&cef.on)['update','notify','eat','drink','setGreenZone','setDemorgan','setEngine','setLocked','setBelt','setVehicle','unknownCommand','setVisible'].forEach(n=>cef.on('hud:'+n,d=>{try{d=JSON.parse(d)}catch(_){}HUD[n](d)}));

/* ===== Georgian Dreams RP gamemode bridge (Pawn -> cef_emit_event) ===== */
let lastSpd=0;
const srvOn=(name,fn)=>{if(!(window.cef&&cef.on))return;cef.on(name,function(){let a=[].slice.call(arguments);
 if(a.length===1&&typeof a[0]==='string'&&/^[\[{]/.test(a[0])){try{a=JSON.parse(a[0]);if(!Array.isArray(a))a=[a]}catch(_){}}
 else if(a.length===1&&Array.isArray(a[0]))a=a[0];
 try{fn.apply(null,a)}catch(_){}})};
const N=(v,d)=>{v=Number(v);return isFinite(v)?v:(d||0)};
srvOn('Speed:update',(spd,fuel,eng,lights,hp,km,doors)=>{const v=S.veh;
 v.in=true;lastSpd=performance.now();v.speed=N(spd);v.fuel=N(fuel);v.engine=!!N(eng);v.locked=!!N(doors);
 v.gear=v.speed<1?'N':Math.min(6,Math.ceil(v.speed/40));render()});
srvOn('show:speed',on=>{if(!N(on)){S.veh.in=false;S.veh.speed=0;render()}});
srvOn('Hud:toggle',v=>{S.srv=!!N(v);render()});
/* Georgian Dreams RP bridge: current Pawn gamemode emits HUD:* events. */
srvOn('HUD:show',v=>{S.srv=!!N(v);render()});
srvOn('HUD:update',(hp,ar,sat,thr,cash,bank)=>{
 S.health=Math.max(0,Math.min(100,N(hp)));
 S.armor=Math.max(0,Math.min(100,N(ar)));
 S.hunger=Math.max(0,Math.min(100,N(sat,100)));
 S.thirst=Math.max(0,Math.min(100,N(thr,100)));
 S.cash=N(cash);S.bank=N(bank);render();
});
srvOn('HUD:meta',(playerid,id,online,maxPlayers,lvl,cash,bank,playSeconds,weapon,ammo,ammoMax)=>{
 S.id=N(id,playerid);S.online=N(online);S.weapon=N(weapon);S.ammo=N(ammo);render();
});
srvOn('HUD:zone',v=>HUD.setGreenZone(!!N(v)));
srvOn('HUD:extra',(job,location,inVehicle,speed,fuel)=>{
 S.veh.in=!!N(inVehicle);S.veh.speed=N(speed);S.veh.fuel=N(fuel);
 if(S.veh.in){lastSpd=performance.now();S.veh.gear=S.veh.speed<1?'N':Math.min(6,Math.ceil(S.veh.speed/40));}
 render();
});
srvOn('interface:on',v=>{S.srv=!!N(v);render()});   /* cef_functions.inc: interfaceCefOn / interfaceCefOff */
srvOn('speedometer:on',on=>{if(!N(on)){S.veh.in=false;S.veh.speed=0;render()}});   /* ActiveSpeedometerCef / DeactiveSpeedometerCef */
srvOn('Setinfos',(hp,ar,sat,thr)=>{S.health=Math.max(0,Math.min(100,N(hp)));S.armor=Math.max(0,Math.min(100,N(ar)));S.hunger=Math.max(0,Math.min(100,N(sat,100)));
 if(thr!==undefined)S.thirst=Math.max(0,Math.min(100,N(thr,100)));
 $('#sAR').classList.remove('hide');$('#sT').classList.remove('hide');render()});
srvOn('Sethud:info',(online,lvl,cash,bank,id,exp,wanted)=>{S.online=N(online);S.cash=N(cash);S.bank=N(bank);S.id=N(id);S.wanted=Math.max(0,Math.min(5,N(wanted)));render()});
srvOn('Setgun',(w,a)=>{S.weapon=N(w);S.ammo=N(a);render()});
srvOn('Hud:info',name=>{if(name)S.name=String(name).replace(/_/g,' ');render()});
srvOn('Hud:notify',(t,msg)=>{
 const types={0:'error',1:'info',2:'success',3:'warn',error:'error',info:'info',success:'success',warning:'warn',warn:'warn'};
 const key=(typeof t==='string'?t.toLowerCase():N(t,1));
 notify(types[key]||'info',String(msg||''));
});
srvOn('Hud:unknowncmd',c=>HUD.unknownCommand(c));
srvOn('Sethud:plus',(id,m)=>{m=N(m);if(m)notify(m>0?'success':'warn',(m>0?'+':'-')+'$'+Math.abs(m).toLocaleString('en-US'),3000)});
srvOn('game:CEF:money',m=>{S.cash=N(m);render()});
srvOn('data:pool:cashmoney',m=>{S.cash=N(m);render()});
srvOn('data:pool:bankmoney',m=>{S.bank=N(m);render()});
/* HUD:playgift(remainingSeconds, ready, visible) — SyncPlaytimeGiftHUD() in the gamemode */
srvOn('HUD:playgift',(rem,ready,vis)=>{const q=S.quest;q.left=Math.max(0,Math.min(CFG.questStart,N(rem)));q.floor=0;q.ready=!!N(ready);q.vis=!!N(vis);q.sync=performance.now();render()});
srvOn('Hud:gift',m=>{m=Math.max(0,Math.floor(N(m)));const q=S.quest;
 if(m!==q.min){if(q.min>=0&&m>q.min)notify('success','თქვენ მიიღეთ უფასო საჩუქარი!',6000);
  q.min=m;q.left=m*60;q.floor=Math.max(0,(m-1)*60)}render()});
srvOn('Hud:greenzone',b=>HUD.setGreenZone(!!N(b)));
srvOn('Hud:demorgan',b=>HUD.setDemorgan(!!N(b)));
/* Real gamemode event, sent on initial HUD sync and /apanel X2 changes. */
srvOn('Hud:paydayBoost',b=>HUD.setPaydayBoost(N(b)));
/* უსაფრთხოება: თუ სიჩქარის მონაცემი 1.5 წმ-ის განმავლობაში არ მოვიდა, სპიდომეტრი იმალება */
setInterval(()=>{if(!CFG.demo&&S.veh.in&&performance.now()-lastSpd>1500){S.veh.in=false;S.veh.speed=0;render()}},500);

/* ===== სამპის ჩაშენებული ჰუდის (მუშტი/ფული/სიცოცხლე) გამორთვა + მონაცემების მოთხოვნა (როგორც ძველ HUD-ში) ===== */
const CEF=window.cef||null;
let HUD_IFACE=false;
const raw=function(){try{if(CEF&&CEF.emit)CEF.emit.apply(CEF,arguments)}catch(_){}};
function nativeHud(){raw('game:hud:setComponentVisible','interface',HUD_IFACE);raw('game:hud:setComponentVisible','chat',true);raw('game:hud:setComponentVisible','radar',true)}
function nativeInit(){nativeHud();raw('game:data:pollPlayerStats',true,50);raw('grp:hud')}
srvOn('Hud:comp',(n,v)=>{if(String(n)==='interface')HUD_IFACE=!!N(v);raw('game:hud:setComponentVisible',String(n),!!N(v))});
if(CEF){nativeInit();setTimeout(nativeInit,1000);setTimeout(nativeInit,3000);setInterval(nativeHud,3000);
 raw('Sethud:info');raw('Setgun');setInterval(()=>{raw('Sethud:info');raw('Setgun')},2000);setInterval(()=>raw('Speed:get'),500)}

/* ===== ციკლები ===== */
let warnH=false,warnT=false;
setInterval(()=>{clock();
 S.hunger=Math.max(0,S.hunger-CFG.hungerDrain);S.thirst=Math.max(0,S.thirst-CFG.thirstDrain);
 if(S.hunger<20&&!warnH){warnH=true;notify('warn','გშია! მიირთვით რამე')}if(S.hunger>=20)warnH=false;
 if(S.thirst<20&&!warnT){warnT=true;notify('warn','გწყურია! დალიეთ რამე')}if(S.thirst>=20)warnT=false;
 const q=S.quest;if(q.left>q.floor&&performance.now()-q.sync>2500)q.left--;
 render()},1000);
$('#qc').onclick=()=>$('#quest').classList.toggle('min');
$('#qi').onclick=()=>notify('info','გაატარე '+CFG.questGoal+' საათი სერვერზე და მიიღე უფასო საჩუქარი',5000);

function fit(){const k=Math.min(innerWidth/1920,innerHeight/1080),h=$('#hud');h.style.width=innerWidth/k+'px';h.style.height=innerHeight/k+'px';h.style.transform='scale('+k+')'}
addEventListener('resize',fit);fit();clock();

/* ===== კლავიშები ===== */
let gas=false;
addEventListener('keydown',e=>{
 if(e.code==='F7'){e.preventDefault();HUD.setVisible(S.userHide);emit('hud:toggle',{visible:!S.userHide});return}
 if(e.repeat)return;
 if(e.code==='Backquote'){$('#dm').classList.toggle('show');return}
 if(e.code==='KeyB'&&!S.talking){S.talking=true;emit('voice',{on:1});render()}
 if(!CFG.demo)return;
 const k=e.code;
 if(k==='ArrowUp')gas=true;
 if(k==='Digit2'&&S.veh.in)HUD.setEngine(!S.veh.engine);
 if(k==='KeyL'&&S.veh.in)HUD.setLocked(!S.veh.locked);
 if(k==='KeyC'&&S.veh.in)HUD.setBelt(!S.veh.belt);
 if(k==='KeyV')HUD.setVehicle(!S.veh.in);
 if(k==='KeyE'){HUD.eat();notify('success','თქვენ მიირთვით საჭმელი')}
 if(k==='KeyR'){HUD.drink();notify('success','თქვენ დალიეთ წყალი')}
 if(k==='KeyG')HUD.setGreenZone(!S.greenzone);
 if(k==='KeyJ')HUD.setDemorgan(!S.demorgan);
 if(k==='KeyP'){S.x2=!S.x2;S.x4=!S.x4;render()}
 if(k==='KeyW'){S.wanted=(S.wanted+1)%6;render()}
 if(k==='KeyN')HUD.unknownCommand('/asdf');
 if(k==='KeyM'||k==='KeyT'||k==='F11')emit('key',{code:k});
 if(k==='KeyO'){S.cash+=50000;S.bank-=20000;render()}
 if(k==='KeyK'){S.radio=!S.radio;render()}
});
addEventListener('keyup',e=>{if(e.code==='ArrowUp')gas=false;if(e.code==='KeyB'&&S.talking){S.talking=false;emit('voice',{on:0});render()}});

/* ===== დემო რეჟიმი (გამორთე CFG.demo=false-ით) ===== */
if(CFG.demo){document.body.classList.add('demo');
 $('#dm').innerHTML='` ღილაკით დამალვა/ჩვენება · V მანქანა · 2 ძრავა · L ჩაკეტვა · C ღვედი · ↑ გაზი · E ჭამა · R სმა<br>G გრინზონა · J დემორგანი · P x2/x4 · W ვარსკვლავი · N შეცდომა · B მიკროფონი (დაჭერა) · K რადიო · O ფული · I Inventory';
 Object.assign(S,{cash:19854637,bank:7576204,wanted:4,hunger:78,thirst:64,greenzone:true});
 S.veh.fuel=85;
 setTimeout(()=>{HUD.setVehicle(true);setTimeout(()=>notify('info','თქვენ გამოიყენეთ მასკა',6000),500);setTimeout(()=>HUD.setEngine(true),1000)},600);
 setInterval(()=>{const v=S.veh;if(!v.in)return;
  if(v.engine&&gas)v.speed=Math.min(230,v.speed+1.8);else v.speed=Math.max(0,v.speed-(v.engine?.7:1.4));
  v.gear=v.speed<1?'N':Math.min(6,Math.ceil(v.speed/40));
  if(v.engine)v.fuel=Math.max(0,v.fuel-(.002+v.speed*.00004));
  render()},50)}
emit('hudReady',{hideNativeHud:true});
render();
